content.starter:
# 1) Блок terraform: перечисляем нужные провайдеры
terraform {
  required_providers {
    # local = {
    #   source  = "hashicorp/local"
    #   version = "~> 2.5"
    # }
  }
}

# 2) Настройка провайдера. Для local настраивать нечего, но блок оставляем.
# provider "local" {}

# 3) Ресурс: файл на диске.
# Синтаксис: resource "<тип>" "<локальное_имя>" { ... }
# resource "local_file" "hello" {
#   filename = "..."
#   content  = "..."
# }

content.solution:
terraform {
  required_providers {
    local = {
      source  = "hashicorp/local"
      version = "~> 2.5"
    }
  }
}

provider "local" {}

resource "local_file" "hello" {
  filename = "hello.txt"
  content  = "Привет от Terraform!\n"
}

content.starter:
# 1. Переменные-входы. Их можно переопределить в terraform.tfvars.
variable "region" {
  # type    = ...
  # default = ...
}

# variable "instance_type" { ... }

# 2. locals — внутренние вычисляемые значения
# locals {
#   project = "shop"
#   name    = "..."
# }

# 3. Ресурс использует var.* и local.*
resource "aws_instance" "web" {
  ami           = "ami-0abcd1234"
  # instance_type = ...
  # tags = { Name = ... }
}

# 4. output — значение наружу
# output "instance_id" { ... }

content.solution:
variable "region" {
  type    = string
  default = "eu-central-1"
}

variable "instance_type" {
  type    = string
  default = "t3.micro"
}

locals {
  project = "shop"
  name    = "${local.project}-web"
}

resource "aws_instance" "web" {
  ami           = "ami-0abcd1234"
  instance_type = var.instance_type

  tags = {
    Name = local.name
  }
}

output "instance_id" {
  value = aws_instance.web.id
}

content.starter:
# 1. Опишите переменную environment (string, default = "dev").
variable "environment" {
  # ...
}

# 2. Подключите модуль web из локальной папки ./modules/server
#    и передайте ему name и environment.
module "web" {
  # source = ...
  # ...
}

# 3. Верните адрес наружу через output web_address (module.web.ip_address).

content.solution:
variable "environment" {
  type    = string
  default = "dev"
}

module "web" {
  source      = "./modules/server"
  name        = "web-1"
  environment = var.environment
}

output "web_address" {
  value = module.web.ip_address
}
